head.script:
scwin.onpageload = function() {
	wdc_main.createWindow("TEST1", null, "windowContainer_accessibility_WESD-1586_(WSQ-5576)_component3.xml", "TEST1", "TEST1");
	wdc_main.createWindow("TEST2", null, "windowContainer_accessibility_WESD-1586_(WSQ-5576)_component4.xml", "TEST2", "TEST2");
};

	scwin.checkVal1 = function() {
		const parentDiv = WebSquare.wUnit.getDomById('wdc_main');
		const childDivs = parentDiv.children;
		let return_check = false;

		// Check the order of the child elements
		if (childDivs.length >= 2) {
			if (childDivs[0].id === 'mf_wdc_main_toolbar' && childDivs[1].id === 'mf_wdc_main_window') {
				return_check = true;
			} else {
				return_check = false;
			}
		} else {
			return_check = false;
		}
		return return_check;
	}	

	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
